package com.rebuildbank;

import java.text.NumberFormat;
import java.util.Locale;

final class Amounts
{
	private Amounts()
	{
	}

	/** Parses "10m", "2.5b", "500k", "1,000,000". Returns -1 if invalid. */
	static long parse(String text)
	{
		if (text == null)
		{
			return -1;
		}
		String s = text.trim().toLowerCase(Locale.ROOT).replace(",", "").replace(" ", "");
		if (s.isEmpty())
		{
			return -1;
		}
		double mult = 1;
		char last = s.charAt(s.length() - 1);
		if (last == 'k' || last == 'm' || last == 'b')
		{
			mult = last == 'k' ? 1e3 : last == 'm' ? 1e6 : 1e9;
			s = s.substring(0, s.length() - 1);
		}
		try
		{
			double v = Double.parseDouble(s) * mult;
			return v < 0 || v > Long.MAX_VALUE ? -1 : (long) v;
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	static String format(long v)
	{
		return NumberFormat.getIntegerInstance(Locale.US).format(v);
	}

	/** Like the game's own stack numbers: 99999, then 100K, then 10M. */
	static String stackFormat(long v)
	{
		if (v >= 10_000_000L)
		{
			return (v / 1_000_000L) + "M";
		}
		if (v >= 100_000L)
		{
			return (v / 1_000L) + "K";
		}
		return Long.toString(v);
	}

	/** 1.2M style, for compact labels. */
	static String shortFormat(long v)
	{
		long a = Math.abs(v);
		if (a >= 1_000_000_000L)
		{
			return String.format(Locale.US, "%.2fB", v / 1e9);
		}
		if (a >= 1_000_000L)
		{
			return String.format(Locale.US, "%.2fM", v / 1e6);
		}
		if (a >= 10_000L)
		{
			return String.format(Locale.US, "%.1fK", v / 1e3);
		}
		return format(v);
	}
}

package com.rebuildbank;

/** How the goal is shown in the timer overlay. */
public enum GoalDisplay
{
	OFF("Hidden"),
	PERCENT("Percentage"),
	VALUE("Value"),
	BOTH("Value and percentage");

	private final String label;

	GoalDisplay(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.rebuildbank;

public enum GoalType
{
	NONE("No goal"),
	NET_VALUE("Temporary bank value (gp)"),
	COINS("Coins in temporary bank"),
	ITEM("Quantity of an item");

	private final String label;

	GoalType(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.rebuildbank;

import java.util.Collections;
import java.util.List;
import lombok.Builder;
import lombok.Value;

/** Immutable snapshot built on the client thread and rendered on the Swing thread. */
@Value
@Builder
class PanelData
{
	static final PanelData LOGGED_OUT = PanelData.builder().status("Log in to use Temporary Rebuild Bank").build();

	boolean loggedIn;
	boolean active;
	boolean paused;
	/** Started (the starting point is recorded), so it can be paused. */
	boolean pausable;
	boolean hasDebt;
	String status;
	String time;
	long bankValue;
	long spent;
	long debt;
	long netValue;
	long gpPerHour;
	GoalType goalType;
	long goalTarget;
	long goalProgress;
	String goalItemName;
	boolean complete;
	long violations;
	long pkKills;
	long pkAverage;
	@Builder.Default
	List<Row> items = Collections.emptyList();

	@Value
	static class Row
	{
		String name;
		long quantity;
		long value;
	}
}

package com.rebuildbank;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;

/** Perdu repair / Lost Property shop prices, keyed by lower-case item name. */
@Slf4j
final class PerduCosts
{
	private static final Map<String, Long> COSTS = load();

	private PerduCosts()
	{
	}

	/** Cost for an item name, or -1 if Perdu doesn't handle it. */
	static long cost(String itemName)
	{
		return itemName == null ? -1 : COSTS.getOrDefault(itemName.toLowerCase(Locale.ROOT), -1L);
	}

	private static Map<String, Long> load()
	{
		Map<String, Long> map = new HashMap<>();
		try (InputStream in = PerduCosts.class.getResourceAsStream("perdu_costs.txt"))
		{
			if (in == null)
			{
				return Collections.emptyMap();
			}
			BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			for (String line; (line = r.readLine()) != null; )
			{
				line = line.trim();
				int eq = line.lastIndexOf('=');
				if (line.isEmpty() || line.startsWith("#") || eq < 0)
				{
					continue;
				}
				map.put(line.substring(0, eq).trim().toLowerCase(Locale.ROOT), Long.parseLong(line.substring(eq + 1).trim()));
			}
		}
		catch (IOException | NumberFormatException e)
		{
			log.warn("Couldn't load Perdu costs", e);
		}
		return map;
	}
}

package com.rebuildbank;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Units;

@ConfigGroup(RebuildBankConfig.GROUP)
public interface RebuildBankConfig extends Config
{
	String GROUP = "rebuildbank";

	@ConfigSection(name = "Untradeables", description = "Untradeables already in your bank when you start", position = 10)
	String untradeableSection = "untradeables";

	@ConfigSection(name = "Timer overlay", description = "In-game timer", position = 20)
	String overlaySection = "overlay";

	@ConfigItem(
		keyName = "showRebuildView",
		name = "Show temporary bank",
		description = "Show your temporary bank instead of your real bank. Can also be toggled from the button in the bank.",
		position = 1
	)
	default boolean showRebuildView()
	{
		return true;
	}

	@ConfigItem(
		keyName = "buyTradeables",
		name = "Buy from hidden bank",
		description = "Lets you withdraw tradeables from your real (hidden) bank by paying for them.<br>"
			+ "Each one costs its Grand Exchange price, paid only with coins in your temporary bank - "
			+ "the coins in your real bank are never used "
			+ "(anything your coins can't cover shows as debt).<br>"
			+ "Off: you can only withdraw what's in your temporary bank.",
		position = 2
	)
	default boolean buyTradeables()
	{
		return false;
	}

	@ConfigItem(
		keyName = "limitGeBuys",
		name = "Limit GE buys",
		description = "Blocks confirming a Grand Exchange buy offer that costs more than the coins you can spend: "
			+ "coins in your inventory and temporary bank, minus any coins you owe your real bank.<br>"
			+ "If the GE takes coins from your bank, they come out of your temporary bank's coins.<br>"
			+ "Only while you're viewing your temporary bank - in the real bank view, GE offers aren't limited.",
		position = 3
	)
	default boolean limitGeBuys()
	{
		return true;
	}

	@ConfigItem(
		keyName = "valueUntradeables",
		name = "Value untradeables",
		description = "Count untradeable items in your temporary bank at their high alch value (otherwise 0 gp)",
		position = 4
	)
	default boolean valueUntradeables()
	{
		return false;
	}

	@ConfigItem(
		keyName = "carriedAreBorrowed",
		name = "Starting items are owed",
		description = "On: tradeables you're wearing or carrying when you press Start came from your real bank, "
			+ "so they show as owed (in red) until you deposit them back. Eating, spending or dropping them "
			+ "keeps them owed until you replace them.<br>"
			+ "Untradeables you start with are locked like the ones in your bank once you deposit them.<br>"
			+ "Off: everything you start with is yours and counts as progress.<br>"
			+ "Untradeables you get during the run are always yours.",
		position = 5
	)
	default boolean carriedAreBorrowed()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat messages",
		description = "Show chat messages for deposits, withdrawals and rule breaks",
		position = 6
	)
	default boolean chatMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyGoal",
		name = "Notify on goal",
		description = "Send a notification when the goal is reached",
		position = 7
	)
	default boolean notifyGoal()
	{
		return true;
	}

	// ---- untradeables ----

	@ConfigItem(
		keyName = "untradeableMode",
		name = "Unlock cost",
		description = "Untradeables already in your bank when you start:<br>"
			+ "Locked: they can't be unlocked at all.<br>"
			+ "Free: right-click them in the bank and choose Unlock, for free.<br>"
			+ "Perdu price: pay once per item what Perdu charges to repair/replace it.<br>"
			+ "Custom price: pay once per item the price in your unlock list.<br>"
			+ "Paid only with coins in your temporary bank - the coins in your real bank are never used "
			+ "and stay where they are.<br>"
			+ "Untradeables you get during the run are always yours.",
		position = 11,
		section = untradeableSection
	)
	default UntradeableMode untradeableMode()
	{
		return UntradeableMode.NOT_ALLOWED;
	}

	@ConfigItem(
		keyName = "untradeableFilter",
		name = "Unlockable items",
		description = "Which existing untradeables can be unlocked:<br>"
			+ "Perdu items: things Perdu repairs or sells back (fire/infernal cape, defenders, void, god capes...).<br>"
			+ "Combat gear: any untradeable gear with combat stats (adds skillcapes, cosmetic defenders...).<br>"
			+ "Everything: every untradeable, including quest items and clue junk (not recommended).<br>"
			+ "Only my unlock list: just the items you list below, nothing else.<br>"
			+ "Items in your unlock list are unlockable whichever preset you pick (unless Unlock cost is Locked).<br>"
			+ "Rune pouches are offered with every preset except 'Only my unlock list' (you can only own one).<br>"
			+ "Charged, degraded or combined versions of tradeable gear (tentacle, bowfa, crystal armour, degraded "
			+ "barrows, charged chainmace/Tumeken's shadow...) are never untradeables - they count as normal items.",
		position = 12,
		section = untradeableSection
	)
	default UntradeableFilter untradeableFilter()
	{
		return UntradeableFilter.COMBAT;
	}

	@ConfigItem(
		keyName = "untradeableAlwaysAllow",
		name = "My unlock list",
		description = "Untradeables that are unlockable whatever the preset (unless Unlock cost is Locked), "
			+ "one per line. Add a price to use with "
			+ "Unlock cost 'Custom price', e.g.<br>Fire cape: 1m<br>Infernal cape: 5m<br>Graceful*<br>"
			+ "A trailing * matches any ending. Items without a price cost the 'Cost for other items'.",
		position = 13,
		section = untradeableSection
	)
	default String untradeableAlwaysAllow()
	{
		return "Fire cape: 1m\nInfernal cape: 5m";
	}

	@ConfigItem(
		keyName = "untradeableNeverAllow",
		name = "Never unlockable",
		description = "Untradeables that can never be unlocked, comma separated or one per line. "
			+ "A trailing * matches any ending. Wins over everything else.",
		position = 14,
		section = untradeableSection
	)
	default String untradeableNeverAllow()
	{
		return "";
	}

	@ConfigItem(
		keyName = "defaultUntradeableCost",
		name = "Cost for other items",
		description = "Unlock cost for items without a price in your unlock list (Custom price) or that Perdu "
			+ "doesn't handle (Perdu price). Accepts 1m, 500k etc.",
		position = 15,
		section = untradeableSection
	)
	default String defaultUntradeableCost()
	{
		return "1m";
	}

	// ---- overlay ----

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show overlay",
		description = "Show the timer and stats overlay in the game. Choose the lines below.",
		position = 21,
		section = overlaySection
	)
	default boolean showOverlay()
	{
		return true;
	}

	@Units(Units.MINUTES)
	@ConfigItem(
		keyName = "timeLimitMinutes",
		name = "Time limit",
		description = "Counts down from this; when it hits zero the timer flashes. 0 = no limit. Set it from the side panel.",
		hidden = true,
		position = 22,
		section = overlaySection
	)
	default int timeLimitMinutes()
	{
		return 60;
	}

	@ConfigItem(
		keyName = "overlayTimeLeft",
		name = "Time left",
		description = "Time left on your time limit (only when one is set in the side panel). "
			+ "The overlay still flashes when time runs out.",
		position = 23,
		section = overlaySection
	)
	default boolean overlayTimeLeft()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayElapsed",
		name = "Elapsed time",
		description = "In-game time since you pressed Start",
		position = 24,
		section = overlaySection
	)
	default boolean overlayElapsed()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayGoal",
		name = "Goal",
		description = "How to show your goal: hidden, a percentage, the value (e.g. 12.5m / 50m), or both. "
			+ "Only shown when you have a goal.",
		position = 25,
		section = overlaySection
	)
	default GoalDisplay overlayGoal()
	{
		return GoalDisplay.BOTH;
	}

	@ConfigItem(
		keyName = "overlayNetValue",
		name = "Net value",
		description = "Temporary bank value minus anything owed",
		position = 26,
		section = overlaySection
	)
	default boolean overlayNetValue()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayGpHr",
		name = "GP/hr",
		description = "Net value per hour of in-game time",
		position = 27,
		section = overlaySection
	)
	default boolean overlayGpHr()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayOwed",
		name = "Owed",
		description = "Value you owe your real bank (only when there is any)",
		position = 28,
		section = overlaySection
	)
	default boolean overlayOwed()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overlayPks",
		name = "PK stats",
		description = "Player kills and average kill value (only after your first PK)",
		position = 29,
		section = overlaySection
	)
	default boolean overlayPks()
	{
		return true;
	}
}

package com.rebuildbank;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Rectangle;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import javax.swing.Scrollable;
import javax.swing.ScrollPaneConstants;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.ProgressBar;

class RebuildBankPanel extends PluginPanel
{
	private static final int MAX_ROWS = 60;
	private static final Color GOAL_FILL = new Color(0x2E, 0xA0, 0x43);

	private final RebuildBankPlugin plugin;

	private final JLabel status = new JLabel();
	private final JButton startButton = new JButton("Start new temporary bank");
	private final JButton endButton = new JButton("End temporary bank");
	private final JButton pauseButton = new JButton("Pause");
	private final JButton clearDebtButton = new JButton("Clear debt");
	private boolean paused;
	private final JCheckBox viewToggle = new JCheckBox("Show temporary bank in bank");

	private final JComboBox<GoalType> goalType = new JComboBox<>(GoalType.values());
	private final JTextField goalItem = new JTextField();
	private final JTextField goalAmount = new JTextField();
	private final JButton setGoalButton = new JButton("Set goal");
	private final JSpinner timeLimit = new JSpinner(new SpinnerNumberModel(60, 0, 100_000, 5));
	private boolean updatingTimeLimit;
	private final JLabel goalItemLabel = new JLabel("Item name or ID");

	private final JLabel time = value();
	private final JLabel bankValue = value();
	private final JLabel spent = value();
	private final JLabel debt = value();
	private final JLabel netValue = value();
	private final JLabel gpHr = value();
	private final JLabel violations = value();
	private final JPanel pkPanel = new JPanel(new GridLayout(0, 2, 4, 3));
	private final JLabel pkKills = value();
	private final JLabel pkAverage = value();
	private final JLabel pkKillsName = new JLabel("Player kills");
	private final JLabel pkAverageName = new JLabel("Avg kill value");
	private final ProgressBar progress = new ProgressBar();
	private final JLabel goalText = new JLabel();

	private final JPanel itemList = new JPanel();

	RebuildBankPanel(RebuildBankPlugin plugin, boolean showView, int timeLimitMinutes)
	{
		// Not wrapped: the panel fills the whole sidebar so the credits can sit at the very bottom
		super(false);
		this.plugin = plugin;
		setBorder(new EmptyBorder(8, 8, 8, 8));
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel root = new JPanel();
		root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));

		JLabel title = new JLabel("Temporary Rebuild Bank");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		root.add(left(title));
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		root.add(left(status));
		root.add(gap());

		JPanel buttons = new JPanel(new GridLayout(3, 1, 0, 4));
		buttons.add(startButton);
		buttons.add(pauseButton);
		buttons.add(endButton);
		root.add(left(buttons));
		viewToggle.setSelected(showView);
		root.add(left(viewToggle));
		root.add(gap());

		// Goal
		root.add(left(header("Goal")));
		JPanel goal = new JPanel(new GridLayout(0, 1, 0, 3));
		goal.add(goalType);
		goal.add(goalItemLabel);
		goal.add(goalItem);
		goal.add(new JLabel("Target (e.g. 10m, 500k, 25)"));
		goal.add(goalAmount);
		goal.add(setGoalButton);
		root.add(left(goal));
		root.add(gap());
		goalText.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		root.add(left(goalText));
		progress.setMaximumValue(100);
		progress.setBackground(ColorScheme.DARKER_GRAY_COLOR); // empty part
		progress.setForeground(GOAL_FILL); // filled part
		progress.setPreferredSize(new Dimension(100, 16));
		progress.setMaximumSize(new Dimension(Integer.MAX_VALUE, 16));
		root.add(left(progress));
		root.add(gap());

		// Challenge time limit, right here for quick changes
		root.add(left(header("Time limit")));
		JPanel limit = new JPanel(new BorderLayout(6, 0));
		JLabel limitLabel = new JLabel("Minutes (0 = no limit)");
		limitLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		limit.add(limitLabel, BorderLayout.CENTER);
		timeLimit.setPreferredSize(new Dimension(80, 24));
		timeLimit.setValue(Math.max(0, timeLimitMinutes));
		limit.add(timeLimit, BorderLayout.EAST);
		root.add(left(limit));
		root.add(gap());

		// Stats
		root.add(left(header("Stats")));
		JPanel stats = new JPanel(new GridLayout(0, 2, 4, 3));
		stat(stats, "In-game time", time);
		stat(stats, "Bank value", bankValue);
		stat(stats, "Paid out", spent);
		stat(stats, "Owed to real bank", debt);
		stat(stats, "Net value", netValue);
		stat(stats, "GP / hour", gpHr);
		stat(stats, "Rule breaks", violations);

		root.add(left(stats));
		clearDebtButton.setToolTipText("Forgive everything owed, if it was a mistake");
		root.add(left(clearDebtButton));
		pkStat(pkPanel, pkKillsName, pkKills);
		pkStat(pkPanel, pkAverageName, pkAverage);
		pkPanel.setVisible(false);
		root.add(left(pkPanel));
		root.add(gap());

		root.add(left(header("Temporary bank")));
		itemList.setLayout(new GridLayout(0, 1, 0, 2));
		root.add(left(itemList));

		JLabel credits = new JLabel("<html>Credits: <font color='#ffffff'>shieldman4</font></html>");
		credits.setFont(FontManager.getRunescapeSmallFont());
		credits.setForeground(ColorScheme.BRAND_ORANGE);
		credits.setHorizontalAlignment(SwingConstants.CENTER);
		credits.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(1, 0, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			new EmptyBorder(6, 0, 0, 0)));

		// Everything above the credits scrolls; the credits stay pinned to the bottom
		JPanel top = new WidthTrackingPanel();
		top.add(root, BorderLayout.NORTH);
		JScrollPane scroll = new JScrollPane(top,
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED, ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(null);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);
		add(credits, BorderLayout.SOUTH);

		startButton.addActionListener(e ->
		{
			if (endButton.isEnabled() && JOptionPane.showConfirmDialog(this,
				"Start a new temporary bank? Your current temporary bank progress will be lost.",
				"Temporary Rebuild Bank", JOptionPane.OK_CANCEL_OPTION) != JOptionPane.OK_OPTION)
			{
				return;
			}
			plugin.startSession();
		});
		endButton.addActionListener(e ->
		{
			if (JOptionPane.showConfirmDialog(this,
				"End this temporary bank? Your real bank is untouched; temporary bank progress will be cleared.",
				"Temporary Rebuild Bank", JOptionPane.OK_CANCEL_OPTION) == JOptionPane.OK_OPTION)
			{
				plugin.endSession();
			}
		});
		pauseButton.addActionListener(e -> plugin.setPaused(!paused));
		clearDebtButton.addActionListener(e ->
		{
			if (JOptionPane.showConfirmDialog(this,
				"<html>Clear all debt (" + debt.getText() + ")?<br><br>"
					+ "Only do this if it was a genuine mistake, e.g. a shop or the Grand Exchange<br>"
					+ "took coins straight from your real bank. Owed items stop being owed and<br>"
					+ "unpaid costs are wiped. This can't be undone.</html>",
				"Temporary Rebuild Bank", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.OK_OPTION)
			{
				plugin.clearDebt();
			}
		});
		viewToggle.addActionListener(e -> plugin.setViewEnabled(viewToggle.isSelected()));
		timeLimit.addChangeListener(e ->
		{
			if (!updatingTimeLimit)
			{
				plugin.setTimeLimit((Integer) timeLimit.getValue());
			}
		});
		goalType.addActionListener(e -> updateGoalInputs());
		setGoalButton.addActionListener(e ->
		{
			GoalType type = (GoalType) goalType.getSelectedItem();
			long amount = type == GoalType.NONE ? 0 : Amounts.parse(goalAmount.getText());
			if (type != GoalType.NONE && amount <= 0)
			{
				JOptionPane.showMessageDialog(this, "Enter a target like 10m, 500k or 25.");
				return;
			}
			plugin.setGoal(type, goalItem.getText().trim(), amount);
		});

		updateGoalInputs();
		update(PanelData.LOGGED_OUT);
	}

	void setTimeLimit(int minutes)
	{
		updatingTimeLimit = true;
		timeLimit.setValue(Math.max(0, minutes));
		updatingTimeLimit = false;
	}

	void setViewToggle(boolean on)
	{
		viewToggle.setSelected(on);
	}

	void showMessage(String message)
	{
		JOptionPane.showMessageDialog(this, message, "Temporary Rebuild Bank", JOptionPane.INFORMATION_MESSAGE);
	}

	/** Must be called on the Swing thread. */
	void update(PanelData d)
	{
		status.setText("<html>" + d.getStatus() + "</html>");
		startButton.setEnabled(d.isLoggedIn());
		endButton.setEnabled(d.isActive());
		paused = d.isPaused();
		pauseButton.setEnabled(d.isActive() && d.isPausable());
		pauseButton.setText(paused ? "Resume" : "Pause");
		pauseButton.setToolTipText(paused
			? "Resume: the bank as it is now becomes your new starting point"
			: "Pause: stop the timer and use your real bank freely - nothing counts until you resume");
		clearDebtButton.setVisible(d.isActive() && d.isHasDebt());
		setGoalButton.setEnabled(d.isActive());

		if (!d.isActive())
		{
			pkPanel.setVisible(false);
			for (JLabel l : new JLabel[]{time, bankValue, spent, debt, netValue, gpHr, violations})
			{
				l.setText("-");
			}
			goalText.setText("");
			progress.setValue(0);
			progress.setCenterLabel("");
			progress.setLeftLabel("");
			progress.setRightLabel("");
			itemList.removeAll();
			revalidate();
			repaint();
			return;
		}

		time.setText(d.getTime());
		bankValue.setText(Amounts.shortFormat(d.getBankValue()));
		spent.setText(Amounts.shortFormat(d.getSpent()));
		debt.setText(d.getDebt() > 0 ? "-" + Amounts.shortFormat(d.getDebt()) : "0");
		debt.setForeground(d.getDebt() > 0 ? ColorScheme.PROGRESS_ERROR_COLOR : Color.WHITE);
		netValue.setText(Amounts.shortFormat(d.getNetValue()));
		gpHr.setText(Amounts.shortFormat(d.getGpPerHour()));
		violations.setText(Amounts.format(d.getViolations()));
		boolean pk = d.getPkKills() > 0;
		pkPanel.setVisible(pk);
		pkKills.setText(Amounts.format(d.getPkKills()));
		pkAverage.setText(Amounts.shortFormat(d.getPkAverage()));
		violations.setForeground(d.getViolations() > 0 ? ColorScheme.PROGRESS_ERROR_COLOR : Color.WHITE);

		if (d.getGoalType() == null || d.getGoalType() == GoalType.NONE || d.getGoalTarget() <= 0)
		{
			goalText.setText("No goal set");
			progress.setValue(0);
			progress.setCenterLabel("");
			progress.setLeftLabel("");
			progress.setRightLabel("");
		}
		else
		{
			String what = d.getGoalType() == GoalType.ITEM ? d.getGoalItemName() : d.getGoalType().toString();
			goalText.setText("<html>" + what + ": " + Amounts.format(d.getGoalTarget())
				+ (d.isComplete() ? " <font color='#00ff00'>(complete!)</font>" : "") + "</html>");
			int pct = (int) Math.max(0, Math.min(100, d.getGoalProgress() * 100 / d.getGoalTarget()));
			progress.setValue(pct);
			progress.setLeftLabel(Amounts.shortFormat(d.getGoalProgress()));
			progress.setRightLabel(Amounts.shortFormat(d.getGoalTarget()));
			progress.setCenterLabel(pct + "%");
		}

		itemList.removeAll();
		if (d.getItems().isEmpty())
		{
			JLabel empty = new JLabel("Empty - deposit something!");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			itemList.add(empty);
		}
		int shown = 0;
		for (PanelData.Row r : d.getItems())
		{
			if (shown++ >= MAX_ROWS)
			{
				JLabel more = new JLabel("... and " + (d.getItems().size() - MAX_ROWS) + " more");
				more.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				itemList.add(more);
				break;
			}
			JPanel row = new JPanel(new BorderLayout());
			row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			row.setBorder(new EmptyBorder(3, 5, 3, 5));
			JLabel name = new JLabel(r.getName() + " x " + Amounts.shortFormat(r.getQuantity()));
			name.setForeground(Color.WHITE);
			JLabel val = new JLabel(Amounts.shortFormat(r.getValue()));
			val.setForeground(ColorScheme.GRAND_EXCHANGE_PRICE);
			row.add(name, BorderLayout.CENTER);
			row.add(val, BorderLayout.EAST);
			itemList.add(row);
		}
		revalidate();
		repaint();
	}

	private void updateGoalInputs()
	{
		GoalType type = (GoalType) goalType.getSelectedItem();
		boolean item = type == GoalType.ITEM;
		goalItem.setEnabled(item);
		goalItemLabel.setEnabled(item);
		goalAmount.setEnabled(type != GoalType.NONE);
	}

	private static JLabel value()
	{
		JLabel l = new JLabel("-", SwingConstants.RIGHT);
		l.setForeground(Color.WHITE);
		return l;
	}

	private static void stat(JPanel p, String name, JLabel v)
	{
		JLabel n = new JLabel(name);
		n.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		p.add(n);
		p.add(v);
	}

	private static void pkStat(JPanel p, JLabel name, JLabel v)
	{
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		p.add(name);
		p.add(v);
	}

	private static JLabel header(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(ColorScheme.BRAND_ORANGE);
		l.setBorder(BorderFactory.createEmptyBorder(0, 0, 3, 0));
		return l;
	}

	private static JComponent left(JComponent c)
	{
		c.setAlignmentX(LEFT_ALIGNMENT);
		return c;
	}

	/** Scroll content that always matches the sidebar's width, so nothing spills off the right edge. */
	private static class WidthTrackingPanel extends JPanel implements Scrollable
	{
		WidthTrackingPanel()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private static JComponent gap()
	{
		return left((JComponent) Box.createVerticalStrut(10));
	}
}

