	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!RebuildBankConfig.GROUP.equals(e.getGroup()))
		{
			return;
		}
		if ("showRebuildView".equals(e.getKey()))
		{
			if (panel != null)
			{
				SwingUtilities.invokeLater(() -> panel.setViewToggle(config.showRebuildView()));
			}
			clientThread.invokeLater(this::rebuildBankInterface);
		}
		else if ("timeLimitMinutes".equals(e.getKey()))
		{
			RebuildBankPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(() -> p.setTimeLimit(config.timeLimitMinutes()));
			}
		}
		else if (e.getKey().startsWith("untradeable") || "valueUntradeables".equals(e.getKey())
			|| "defaultUntradeableCost".equals(e.getKey()))
		{
			clientThread.invokeLater(() ->
			{
				checkGoal();
				refreshPanel();
				rebuildBankInterface();
			});
		}
	}

	// ------------------------------------------------------------------ bank interface

	private void applyBankView()
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.isHidden())
		{
			return;
		}
		Widget sepLine = findNamed(container, SEPARATOR_LINE);
		Widget sepText = findNamed(container, SEPARATOR_TEXT);
		hideAll(container, OWED_PREFIX);
		if (session == null || session.baselinePending || !tempViewActive())
		{
			hide(sepLine);
			hide(sepText);
			return;
		}
		Widget[] children = container.getChildren();
		if (children == null)
		{
			return;
		}

		// Keep the bank's own order (respects the selected tab and search), but only
		// show your temporary bank, packed into a gap-free grid, then a divider and
		// the existing untradeables you can unlock.
		RebuildSession.Policy policy = policy();
		Map<Integer, Long> lockable = session.unlockable(policy);
		List<Widget> owned = new ArrayList<>();
		List<Widget> locked = new ArrayList<>();
		Map<Integer, Boolean> seen = new HashMap<>();
		for (Widget c : children)
		{
			if (c == null || c.isHidden() || isOurs(c))
			{
				continue;
			}
			int id = c.getItemId();
			boolean itemSlot = c.getOriginalWidth() == ITEM_WIDTH && c.getOriginalHeight() == ITEM_HEIGHT;
			if (!itemSlot || id <= 0 || id == ItemID.BANK_FILLER)
			{
				// tab separators, tab labels, empty slots and fillers
				c.setHidden(true);
				continue;
			}
			ItemComposition def = client.getItemDefinition(id);
			int canon = def.getPlaceholderTemplateId() >= 0 ? -1 : itemManager.canonicalize(id);
			long have = canon > 0 ? session.count(canon) : 0;
			long lockedQty = canon > 0 ? lockable.getOrDefault(canon, 0L) : 0;
			if (have + lockedQty <= 0 || seen.putIfAbsent(canon, true) != null)
			{
				c.setHidden(true);
				continue;
			}
			if (have > 0)
			{
				c.setItemQuantity((int) Math.min(Integer.MAX_VALUE, have));
				c.setOpacity(0);
				owned.add(c);
			}
			else
			{
				// Locked: faded. Its game options are left alone; "Unlock" is added to the
				// right-click menu as a client-only entry (see onMenuEntryAdded).
				c.setItemQuantity((int) Math.min(Integer.MAX_VALUE, lockedQty));
				c.setOpacity(110);
				locked.add(c);
			}
		}

		Comparator<Widget> order = Comparator.comparingInt(Widget::getOriginalY).thenComparingInt(Widget::getOriginalX);
		owned.sort(order);
		locked.sort(order);
		int gridWidth = (ITEMS_PER_ROW - 1) * ITEM_X_STEP + ITEM_WIDTH;

		// Anything taken out of the real bank beyond the limit goes at the very top, in red
		int ownedTop = layoutOwed(container, gridWidth);
		int y = layoutGrid(owned, ownedTop);

		// Your temporary bank always keeps at least 4 rows of room above the
		// untradeables, empty or not, so there's space to see it fill up.
		y = Math.max(y, ownedTop + MIN_ROWS * ITEM_Y_STEP);

		if (!locked.isEmpty())
		{
			int top = y + SECTION_GAP;
			if (sepText == null)
			{
				sepText = container.createChild(-1, WidgetType.TEXT);
				sepText.setName(SEPARATOR_TEXT);
				sepText.setFontId(FONT_PLAIN_11);
				sepText.setTextShadowed(true);
				sepText.setXTextAlignment(WidgetTextAlignment.CENTER);
				sepText.setYTextAlignment(WidgetTextAlignment.CENTER);
				sepText.setTextColor(LABEL_COLOR);
			}
			sepText.setText(policy.untradeableMode() == UntradeableMode.ALLOWED
				? "Untradeables - right-click to unlock (free)"
				: "Untradeables - unlock with temporary bank coins");
			sepText.setOriginalX(ITEM_START_X);
			sepText.setOriginalY(top);
			sepText.setOriginalWidth(gridWidth);
			sepText.setOriginalHeight(14);
			sepText.setHidden(false);
			sepText.revalidate();

			if (sepLine == null)
			{
				sepLine = container.createChild(-1, WidgetType.RECTANGLE);
				sepLine.setName(SEPARATOR_LINE);
				sepLine.setFilled(true);
				sepLine.setTextColor(SEPARATOR_COLOR);
			}
			sepLine.setOriginalX(ITEM_START_X);
			sepLine.setOriginalY(top + 16);
			sepLine.setOriginalWidth(gridWidth);
			sepLine.setOriginalHeight(1);
			sepLine.setHidden(false);
			sepLine.revalidate();

			y = layoutGrid(locked, top + 22);
		}
		else
		{
			hide(sepLine);
			hide(sepText);
		}

		int height = Math.max(container.getHeight(), y + 4);
		container.setScrollHeight(height);
		int maxScroll = Math.max(0, height - container.getHeight());
		if (container.getScrollY() > maxScroll)
		{
			container.setScrollY(maxScroll);
		}
		container.revalidateScroll();
		final int scrollY = container.getScrollY();
		clientThread.invokeLater(() ->
			client.runScript(ScriptID.UPDATE_SCROLLBAR, InterfaceID.Bankmain.SCROLLBAR, InterfaceID.Bankmain.ITEMS, scrollY));

		Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
		if (title != null)
		{
			title.setText("Temporary Bank - " + Amounts.format(session.netValue(this::unitValue)) + " gp");
		}
	}

	/**
	 * Draws the "owed to your real bank" section: a red label and each owed item
	 * with a red "-amount". These are our own picture-only widgets with no click
	 * actions (right-click "Clear debt" is added in onMenuOpened). Returns the y
	 * where the temporary bank's own items start.
	 */
	private int layoutOwed(Widget container, int gridWidth)
	{
		Map<Integer, Long> owed = session.getOwed();
		if (owed.isEmpty())
		{
			return 0;
		}

		Widget label = namedChild(container, OWED_PREFIX + "label", WidgetType.TEXT);
		label.setFontId(FONT_PLAIN_11);
		label.setTextShadowed(true);
		label.setXTextAlignment(WidgetTextAlignment.CENTER);
		label.setYTextAlignment(WidgetTextAlignment.CENTER);
		label.setTextColor(OWED_COLOR);
		label.setText("You owe your real bank - deposit these back (right-click to clear)");
		place(label, ITEM_START_X, 0, gridWidth, 14);

		int top = 18;
		int i = 0;
		List<Map.Entry<Integer, Long>> entries = new ArrayList<>(owed.entrySet());
		entries.sort(Map.Entry.comparingByKey());
		for (Map.Entry<Integer, Long> e : entries)
		{
			int x = ITEM_START_X + (i % ITEMS_PER_ROW) * ITEM_X_STEP;
			int iy = top + (i / ITEMS_PER_ROW) * ITEM_Y_STEP;

			Widget icon = namedChild(container, OWED_PREFIX + "item" + i, WidgetType.GRAPHIC);
			icon.setItemId(e.getKey());
			// the real amount picks the right stack picture (a pile of coins, not one coin);
			// the game's own number is hidden and drawn in red below instead
			icon.setItemQuantity((int) Math.min(Integer.MAX_VALUE, e.getValue()));
			icon.setItemQuantityMode(ItemQuantityMode.NEVER);
			icon.setBorderType(1); // the thin black outline the bank draws around every item
			icon.setOpacity(0);
			place(icon, x, iy, ITEM_WIDTH, ITEM_HEIGHT);

			Widget qty = namedChild(container, OWED_PREFIX + "qty" + i, WidgetType.TEXT);
			qty.setFontId(FONT_PLAIN_11);
			qty.setTextShadowed(true);
			qty.setXTextAlignment(WidgetTextAlignment.LEFT);
			qty.setYTextAlignment(WidgetTextAlignment.TOP);
			qty.setTextColor(OWED_COLOR);
			qty.setText("-" + Amounts.stackFormat(e.getValue()));
			place(qty, x, iy - 1, ITEM_WIDTH + 8, 12);
			i++;
		}
		int rows = (i + ITEMS_PER_ROW - 1) / ITEMS_PER_ROW;
		return top + rows * ITEM_Y_STEP + SECTION_GAP;
	}

	private static Widget namedChild(Widget parent, String name, int type)
	{
		Widget w = findNamed(parent, name);
		if (w == null || w.getType() != type)
		{
			w = parent.createChild(-1, type);
			w.setName(name);
		}
		return w;
	}

	private static void place(Widget w, int x, int y, int width, int height)
	{
		w.setOriginalX(x);
		w.setOriginalY(y);
		w.setOriginalWidth(width);
		w.setOriginalHeight(height);
		w.setHidden(false);
		w.revalidate();
	}

	private static boolean isOurs(Widget w)
	{
		String name = w.getName();
		return name != null && name.startsWith(WIDGET_PREFIX);
	}

	private static void hideAll(Widget parent, String prefix)
	{
		Widget[] dynamic = parent.getDynamicChildren();
		if (dynamic != null)
		{
			for (Widget w : dynamic)
			{
				if (w != null && w.getName() != null && w.getName().startsWith(prefix))
				{
					w.setHidden(true);
				}
			}
		}
	}

	/** Lays widgets out in the bank grid starting at y; returns the y below the last row. */
	private static int layoutGrid(List<Widget> widgets, int y)
	{
		for (int i = 0; i < widgets.size(); i++)
		{
			Widget c = widgets.get(i);
			c.setOriginalX(ITEM_START_X + (i % ITEMS_PER_ROW) * ITEM_X_STEP);
			c.setOriginalY(y + (i / ITEMS_PER_ROW) * ITEM_Y_STEP);
			c.revalidate();
		}
		int rows = (widgets.size() + ITEMS_PER_ROW - 1) / ITEMS_PER_ROW;
		return y + rows * ITEM_Y_STEP;
	}

	private static Widget findNamed(Widget parent, String name)
	{
		Widget[] dynamic = parent.getDynamicChildren();
		if (dynamic != null)
		{
			for (Widget w : dynamic)
			{
				if (w != null && name.equals(w.getName()))
				{
					return w;
				}
			}
		}
		return null;
	}

	private static void hide(Widget w)
	{
		if (w != null)
		{
			w.setHidden(true);
		}
	}

	/**
	 * Small square stone button next to the bank's "?" button, in the same style as the
	 * bank's wrench and "?" buttons. Its icon shows the view it switches to: a chest for
	 * the temporary bank, coins for the real bank.
	 */
	private void updateToggleButton()
	{
		Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		Widget title = client.getWidget(InterfaceID.Bankmain.TITLE);
		if (universe == null || title == null)
		{
			return;
		}

		// The button has no name (the game would show it in the mouse-over text),
		// so it's found by reference; the tint and icon have no actions and keep names.
		Widget button = isChildOf(toggleButton, universe) ? toggleButton : null;
		Widget tint = findNamed(universe, TOGGLE_TINT);
		Widget icon = findNamed(universe, TOGGLE_ICON);
		if (session == null || session.baselinePending)
		{
			hide(button);
			hide(tint);
			hide(icon);
			restoreTitle();
			return;
		}

		if (button == null || tint == null || icon == null)
		{
			// (re)create all three so they're layered button -> tint -> icon
			hide(button);
			hide(tint);
			hide(icon);
			button = universe.createChild(-1, WidgetType.GRAPHIC);
			toggleButton = button;
			button.setSpriteId(SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
			button.setHasListener(true);
			final Widget b = button;
			button.setOnMouseOverListener((JavaScriptCallback) ev ->
				b.setSpriteId(SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED));
			button.setOnMouseLeaveListener((JavaScriptCallback) ev ->
				b.setSpriteId(SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL));
			button.setOnOpListener((JavaScriptCallback) ev ->
			{
				if (session != null && session.paused)
				{
					chat("Your temporary bank is paused - press Resume in the side panel to see it again.", true);
					return;
				}
				setViewEnabled(!config.showRebuildView());
			});

			// see-through gold layer over the stone in the temp view; no actions, so clicks go to the button
			tint = universe.createChild(-1, WidgetType.RECTANGLE);
			tint.setName(TOGGLE_TINT);
			tint.setFilled(true);
			tint.setTextColor(TOGGLE_TINT_COLOR);
			tint.setOpacity(TOGGLE_TINT_OPACITY);

			icon = universe.createChild(-1, WidgetType.GRAPHIC);
			icon.setName(TOGGLE_ICON);
		}

		// Same size as the bank's "?" button, just to its right
		net.runelite.api.Point uni = universe.getCanvasLocation();
		Widget tut = client.getWidget(InterfaceID.Bankmain.BANK_TUT);
		int x;
		int y;
		int size;
		if (tut != null && !tut.isHidden())
		{
			x = tut.getCanvasLocation().getX() - uni.getX() + tut.getWidth() + TOGGLE_GAP;
			y = tut.getCanvasLocation().getY() - uni.getY();
			size = tut.getHeight();
		}
		else
		{
			x = 60;
			y = title.getCanvasLocation().getY() - uni.getY();
			size = Math.max(18, title.getHeight());
		}
		place(button, x, y, size, size);
		int iconSize = Math.min(TOGGLE_ICON_SIZE, size);
		place(icon, x + (size - iconSize) / 2, y + (size - iconSize) / 2, iconSize, iconSize);

		boolean tempView = tempViewActive();
		// inset past the stone button's raised border so only its flat face is tinted
		place(tint, x + TOGGLE_TINT_INSET, y + TOGGLE_TINT_INSET,
			size - 2 * TOGGLE_TINT_INSET, size - 2 * TOGGLE_TINT_INSET);
		tint.setHidden(!tempView);
		icon.setSpriteId(tempView ? ToggleSprites.SHOW_REAL.getSpriteId() : ToggleSprites.SHOW_TEMP.getSpriteId());
		button.setAction(0, tempView ? "Show real bank" : "Show temp bank");

		makeRoomInTitle(title, x + size + TOGGLE_GAP + uni.getX());
	}

	/** Our view button; it's unnamed so the mouse-over text is just "Show real bank". */
	private Widget toggleButton;

	private static boolean isChildOf(Widget w, Widget parent)
	{
		if (w == null)
		{
			return false;
		}
		Widget[] dynamic = parent.getDynamicChildren();
		if (dynamic != null)
		{
			for (Widget c : dynamic)
			{
				if (c == w)
				{
					return true;
				}
			}
		}
		return false;
	}

	/** The bank title widget we moved, and where it was, so it can be put back. */
	private Widget movedTitle;
	private int movedTitleBaseX;

	/**
	 * Slide the bank's title text right just enough that it starts after our
	 * button, so long titles (e.g. with bank value plugins) are never covered.
	 */
	private void makeRoomInTitle(Widget title, int minTextCanvasX)
	{
		if (title != movedTitle)
		{
			movedTitle = title;
			movedTitleBaseX = title.getOriginalX();
		}
		// measure from the title's original position
		title.setOriginalX(movedTitleBaseX);
		title.revalidate();

		String text = title.getText() == null ? "" : Text.removeTags(title.getText());
		if (text.isEmpty())
		{
			return;
		}
		int textWidth = title.getFont() != null
			? title.getFont().getTextWidth(text)
			: text.length() * TITLE_CHAR_WIDTH_ESTIMATE;
		int textLeft = title.getCanvasLocation().getX() + (title.getWidth() - textWidth) / 2;
		int shift = minTextCanvasX - textLeft;
		if (shift <= 0)
		{
			return;
		}
		// positive originalX moves right, except for right-aligned widgets
		boolean rightAligned = title.getXPositionMode() == WidgetPositionMode.ABSOLUTE_RIGHT;
		title.setOriginalX(movedTitleBaseX + (rightAligned ? -shift : shift));
		title.revalidate();
	}

	private void restoreTitle()
	{
		if (movedTitle != null)
		{
			movedTitle.setOriginalX(movedTitleBaseX);
			movedTitle.revalidate();
			movedTitle = null;
		}
	}

	/** Re-run the bank's own build script so our view is applied or removed. */
	private void rebuildBankInterface()
	{
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.isHidden())
		{
			return;
		}
		Object[] listener = container.getOnInvTransmitListener();
		if (listener != null)
		{
			client.runScript(listener);
		}
	}

	// ------------------------------------------------------------------ helpers

	/**
	 * One-time moves of settings from older versions, so nobody loses what they set:
	 * 1.0 "Custom costs" are folded into the unlock list, and 1.0's single
	 * "Show value, GP/hr and PKs" switch becomes the separate overlay lines.
	 */
	private void migrateConfig()
	{
		final String group = RebuildBankConfig.GROUP;
		String oldCosts = configManager.getConfiguration(group, "customUntradeableCosts");
		if (oldCosts != null)
		{
			String list = configManager.getConfiguration(group, "untradeableAlwaysAllow");
			configManager.setConfiguration(group, "untradeableAlwaysAllow", UnlockList.merge(list, oldCosts));
			configManager.unsetConfiguration(group, "customUntradeableCosts");
		}
		String oldStats = configManager.getConfiguration(group, "overlayShowStats");
		if (oldStats != null)
		{
			if ("false".equals(oldStats))
			{
				configManager.setConfiguration(group, "overlayNetValue", false);
				configManager.setConfiguration(group, "overlayGpHr", false);
				configManager.setConfiguration(group, "overlayPks", false);
				configManager.setConfiguration(group, "overlayGoal", GoalDisplay.OFF);
			}
			configManager.unsetConfiguration(group, "overlayShowStats");
		}
	}

	private RebuildSession.Policy policy()
	{
		final UntradeableMode mode = config.untradeableMode();
		final UntradeableFilter filter = config.untradeableFilter();
		final UnlockList mine = UnlockList.parse(config.untradeableAlwaysAllow());
		final UnlockList never = UnlockList.parse(config.untradeableNeverAllow());
		final boolean buyTradeables = config.buyTradeables();
		final long fallback = Math.max(0, Amounts.parse(config.defaultUntradeableCost()));
		return new RebuildSession.Policy()
		{
			@Override
			public boolean isUntradeable(int itemId)
			{
				return isTrueUntradeable(itemId);
			}

			@Override
			public boolean alwaysYours(int itemId)
			{
				// You can only own one looting bag, so if it were locked away you could
				// never get another during the run: it's always part of the temporary bank.
				return itemId == ItemID.LOOTING_BAG || itemId == ItemID.LOOTING_BAG_OPEN;
			}

			@Override
			public boolean isUnlockable(int itemId)
			{
				String name = itemManager.getItemComposition(itemId).getName();
				if (never.contains(name))
				{
					return false;
				}
				if (mine.contains(name))
				{
					return true; // the player's own list beats every preset
				}
				if (filter == UntradeableFilter.MY_LIST)
				{
					return false;
				}
				if (runePouchCost(itemId) >= 0)
				{
					return true; // rune pouches are always offered: you can only own one
				}
				switch (filter)
				{
					case PERDU:
						return PerduCosts.cost(name) >= 0;
					case ALL:
						return true;
					case COMBAT:
					default:
						return isCombatGear(itemId, name);
				}
			}

			@Override
			public UntradeableMode untradeableMode()
			{
				return mode;
			}

			@Override
			public long untradeableCost(int itemId)
			{
				String name = itemManager.getItemComposition(itemId).getName();
				long pouch = runePouchCost(itemId);
				long otherwise = pouch > 0 ? pouch : fallback;
				switch (mode)
				{
					case REPAIR_COST:
						long perdu = PerduCosts.cost(name);
						return perdu >= 0 ? perdu : otherwise;
					case CUSTOM:
						long listed = mine.price(name);
						return listed >= 0 ? listed : otherwise;
					default:
						return 0;
				}
			}

			@Override
			public boolean buyTradeables()
			{
				return buyTradeables;
			}

			@Override
			public long tradeablePrice(int itemId)
			{
				return itemManager.getItemPrice(itemId);
			}
		};
	}

	/**
	 * What a rune pouch is worth to unlock: a rune pouch note from the Grand Exchange
	 * (swapped for a pouch at any bank), plus a Thread of Elidinis for a divine pouch.
	 * -1 if the item isn't a rune pouch. 0 if the GE price isn't known.
	 */
	private long runePouchCost(int itemId)
	{
		if (itemId != ItemID.BH_RUNE_POUCH && itemId != ItemID.DIVINE_RUNE_POUCH)
		{
			return -1;
		}
		long note = Math.max(0, itemManager.getItemPrice(ItemID.PROMISSORY_NOTE_RUNEPOUCH));
		if (itemId == ItemID.DIVINE_RUNE_POUCH && note > 0)
		{
			return note + Math.max(0, PerduCosts.cost("Thread of Elidinis"));
		}
		return note;
	}

	/**
	 * PvM gear: equippable and gives combat stats (skillcapes, void, defenders and
	 * their cosmetic variants, fire/infernal capes...), or something Perdu repairs.
	 * Quest items, clue junk, cosmetics with no stats etc. are left out.
	 */
	private boolean isCombatGear(int itemId, String name)
	{
		if (PerduCosts.cost(name) >= 0)
		{
			return true;
		}
		ItemStats stats = itemManager.getItemStats(itemId);
		if (stats == null || !stats.isEquipable() || stats.getEquipment() == null)
		{
			return false;
		}
		ItemEquipmentStats e = stats.getEquipment();
		return e.getAstab() != 0 || e.getAslash() != 0 || e.getAcrush() != 0 || e.getAmagic() != 0 || e.getArange() != 0
			|| e.getDstab() != 0 || e.getDslash() != 0 || e.getDcrush() != 0 || e.getDmagic() != 0 || e.getDrange() != 0
			|| e.getStr() != 0 || e.getRstr() != 0 || e.getMdmg() != 0 || e.getPrayer() != 0;
	}

	/** Value of one item in the temporary bank. */
	private long unitValue(int itemId)
	{
		if (itemId == ItemID.COINS)
		{
			return 1;
		}
		ItemComposition def = itemManager.getItemComposition(itemId);
		// Tradeables, and untradeable versions of them (charged/degraded/attached
		// gear like a tentacle, bowfa, degraded barrows, charged Tumeken's shadow),
		// which RuneLite prices from their tradeable parts.
		long price = itemManager.getItemPrice(itemId);
		if (def.isTradeable() || price > 0)
		{
			return price;
		}
		return config.valueUntradeables() ? def.getHaPrice() : 0;
	}

	/**
	 * Untradeable and not just a charged/degraded/combined version of tradeable
	 * items. Those (abyssal tentacle, crystal gear, degraded barrows, charged
	 * weapons...) have a price in RuneLite and are treated as normal bank items.
	 */
	private boolean isTrueUntradeable(int itemId)
	{
		return itemId != ItemID.COINS
			&& !itemManager.getItemComposition(itemId).isTradeable()
			&& itemManager.getItemPrice(itemId) <= 0;
	}

	private Map<Integer, Long> snapshot(ItemContainer container)
	{
		Map<Integer, Long> map = new HashMap<>();
		if (container == null)
		{
			return map;
		}
		for (Item item : container.getItems())
		{
			int id = item.getId();
			if (id <= 0 || item.getQuantity() <= 0 || id == ItemID.BANK_FILLER)
			{
				continue;
			}
			if (client.getItemDefinition(id).getPlaceholderTemplateId() >= 0)
			{
				continue;
			}
			map.merge(itemManager.canonicalize(id), (long) item.getQuantity(), Long::sum);
		}
		return map;
	}

	private void addContainer(Map<Integer, Long> into, int containerId)
	{
		snapshot(client.getItemContainer(containerId)).forEach((id, q) -> into.merge(id, q, Long::sum));
	}


	private int resolveItem(String text)
	{
		if (text == null || text.isEmpty())
		{
			return -1;
		}
		try
		{
			int id = Integer.parseInt(text);
			return id > 0 ? itemManager.canonicalize(id) : -1;
		}
		catch (NumberFormatException ignored)
		{
			// not an id
		}
		return itemManager.search(text).stream()
			.min(Comparator.comparing(p -> !p.getName().equalsIgnoreCase(text)))
			.map(p -> p.getId())
			.orElse(-1);
	}

	private void checkGoal()
	{
		if (session == null || !session.hasGoal() || session.isComplete() || session.baselinePending)
		{
			return;
		}
		if (session.goalProgress(this::unitValue, ItemID.COINS) >= session.goalTarget)
		{
			session.completedAtTicks = session.ticks;
			long net = session.netValue(this::unitValue);
			String msg = "Goal reached in " + RebuildSession.formatTicks(session.completedAtTicks)
				+ " of in-game time! Net value " + Amounts.format(net) + " gp ("
				+ Amounts.format(RebuildSession.gpPerHour(net, session.completedAtTicks)) + " gp/hr).";
			chat(msg);
			if (config.notifyGoal())
			{
				notifier.notify(msg);
			}
		}
	}

	private void reportChanges(List<RebuildSession.Change> changes)
	{
		for (RebuildSession.Change c : changes)
		{
			String name = itemManager.getItemComposition(c.itemId).getName();
			if (c.violated > 0)
			{
				chat(ColorUtil.wrapWithColorTag("You owe " + Amounts.format(c.violated) + " x " + name + "!", Color.RED)
					+ " That came out of your real bank - deposit it back.", true);
			}
			if (c.locked > 0)
			{
				chat("Your starting " + name + (c.locked > 1 ? " (" + Amounts.format(c.locked) + ")" : "")
					+ " is locked like your other untradeables - right-click it in the bank to unlock it.", true);
			}
			if (c.repaid > 0)
			{
				long left = session != null ? session.getOwed().getOrDefault(c.itemId, 0L) : 0;
				chat("Paid back " + Amounts.format(c.repaid) + " x " + name + " to your real bank"
					+ (left > 0 ? " - still owe " + Amounts.format(left) + "." : ". All square!"), true);
			}
			if (c.unlocked > 0 && c.unlockCost > 0)
			{
				chat("Paid " + Amounts.format(c.unlockCost) + " gp for " + Amounts.format(c.unlocked) + " x " + name + ".", true);
			}
			if (!config.chatMessages())
			{
				continue;
			}
			if (c.bought > 0)
			{
				chat("Bought " + Amounts.format(c.bought) + " x " + name + " from your hidden real bank for "
					+ Amounts.format(c.boughtCost) + " gp.");
			}
			if (c.unlocked > 0 && c.unlockCost == 0)
			{
				chat("Took " + Amounts.format(c.unlocked) + " x " + name + " from your existing untradeables.");
			}
		}
	}

	private void chat(String message)
	{
		chat(message, false);
	}

	private void chat(String message, boolean always)
	{
		if (!always && !config.chatMessages() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(ColorUtil.wrapWithColorTag("[Temp Bank] ", CHAT_COLOR) + message)
			.build());
	}

	private void loadSession()
	{
		session = null;
		profileKey = configManager.getRSProfileKey();
		if (profileKey == null)
		{
			return;
		}
		String json = configManager.getConfiguration(RebuildBankConfig.GROUP, profileKey, SESSION_KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}
		session = parseSession(json);
	}

	private RebuildSession parseSession(String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			return gson.fromJson(json, RebuildSession.class);
		}
		catch (JsonSyntaxException ex)
		{
			log.warn("Couldn't read saved rebuild session", ex);
			return null;
		}
	}

	// ------------------------------------------------------------------ backup file (safety net)
	//
	// RuneLite only writes its settings to disk every few minutes and when it closes
	// normally, so if it's killed, recent progress could be lost. Every save is also
	// written straight away to a small backup file in this plugin's own data folder
	// (.runelite/plugin-data/temporary-rebuild-bank), on RuneLite's background thread.
	// On login, whichever copy was saved most recently is used.

	private Filepath backupFile(String rsProfileKey) throws IOException
	{
		return getPluginDirectory().join(rsProfileKey + BACKUP_SUFFIX);
	}

	private void writeBackup(String rsProfileKey, String json)
	{
		executor.execute(() ->
		{
			try
			{
				getPluginDirectory().createDirectories();
				Filepath target = backupFile(rsProfileKey);
				Filepath temp = getPluginDirectory().join(rsProfileKey + BACKUP_SUFFIX + ".tmp");
				temp.write(json, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
				// replace in one step, so a crash mid-write never leaves a broken backup
				temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (IOException ex)
			{
				log.warn("Couldn't write the temporary bank backup", ex);
			}
		});
	}

	private void deleteBackup(String rsProfileKey)
	{
		executor.execute(() ->
		{
			try
			{
				backupFile(rsProfileKey).deleteIfExists();
			}
			catch (IOException ex)
			{
				log.warn("Couldn't delete the temporary bank backup", ex);
			}
		});
	}

	/** After loading from settings, use the backup file instead if it's newer. */
	private void checkBackup()
	{
		final String key = profileKey;
		final RebuildSession loaded = session;
		final long loadedSavedAt = loaded != null ? loaded.savedAtMillis : -1;
		if (key == null)
		{
			return;
		}
		executor.execute(() ->
		{
			String json;
			try
			{
				Filepath file = backupFile(key);
				if (!file.exists())
				{
					return;
				}
				StringBuilder sb = new StringBuilder();
				try (BufferedReader r = file.openBufferedReader())
				{
					for (String line; (line = r.readLine()) != null; )
					{
						sb.append(line);
					}
				}
				json = sb.toString();
			}
			catch (IOException ex)
			{
				log.warn("Couldn't read the temporary bank backup", ex);
				return;
			}
			clientThread.invoke(() ->
			{
				RebuildSession backup = parseSession(json);
				// only if nothing changed while we were reading, and the backup is newer
				if (backup == null || !key.equals(profileKey) || session != loaded
					|| (loaded != null && loaded.savedAtMillis != loadedSavedAt)
					|| backup.savedAtMillis <= loadedSavedAt)
				{
					return;
				}
				session = backup;
				log.debug("Restored temporary bank from backup for {}", key);
				saveSession();
				rebuildBankInterface();
				refreshPanel();
			});
		});
	}

	private void saveSession()
	{
		if (session == null || profileKey == null)
		{
			return;
		}
		session.savedAtMillis = System.currentTimeMillis();
		String json = gson.toJson(session);
		configManager.setConfiguration(RebuildBankConfig.GROUP, profileKey, SESSION_KEY, json);
		writeBackup(profileKey, json);
	}

	/** Builds a snapshot on the client thread and hands it to the panel. */
	private void refreshPanel()
	{
		if (panel == null)
		{
			return;
		}
		PanelData data = buildPanelData();
		RebuildBankPanel p = panel;
		SwingUtilities.invokeLater(() -> p.update(data));
	}

	private PanelData buildPanelData()
	{
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		if (!loggedIn && session == null)
		{
			return PanelData.LOGGED_OUT;
		}
		if (session == null)
		{
			return PanelData.builder().loggedIn(true)
				.status("No temporary bank running.").build();
		}

		List<PanelData.Row> rows = new ArrayList<>();
		long bankValue = 0;
		for (Map.Entry<Integer, Long> e : session.getItems().entrySet())
		{
			long v = unitValue(e.getKey()) * e.getValue();
			bankValue += v;
			rows.add(new PanelData.Row(itemManager.getItemComposition(e.getKey()).getName(), e.getValue(), v));
		}
		rows.sort(Comparator.comparingLong(PanelData.Row::getValue).reversed()
			.thenComparing(PanelData.Row::getName));

		long owedValue = session.owedValue(this::unitValue);
		long net = Math.max(0, bankValue - session.spent - owedValue); // same as RebuildSession.netValue
		long ticks = session.challengeTicks();
		cachedNetValue = net;
		cachedOwedValue = owedValue;
		cachedGoalProgress = session.goalProgress(this::unitValue, ItemID.COINS);
		String status;
		if (session.baselinePending)
		{
			status = "Open your bank to begin.";
		}
		else if (session.paused)
		{
			status = "Paused - your real bank is shown and nothing is tracked.";
		}
		else if (session.resyncPending)
		{
			status = "Resumed - open your bank to continue.";
		}
		else if (session.isComplete())
		{
			status = "Goal complete! Timer stopped.";
		}
		else
		{
			status = "Running (in-game time only).";
		}

		return PanelData.builder()
			.loggedIn(loggedIn)
			.active(true)
			.paused(session.paused)
			.pausable(!session.baselinePending)
			.hasDebt(session.hasDebt())
			.status(status)
			.time(RebuildSession.formatTicks(ticks))
			.bankValue(bankValue)
			.spent(session.paid)
			.debt(session.spent + cachedOwedValue)
			.netValue(net)
			.gpPerHour(RebuildSession.gpPerHour(net, ticks))
			.goalType(session.goalType)
			.goalTarget(session.goalTarget)
			.goalProgress(cachedGoalProgress)
			.goalItemName(session.goalItemName)
			.complete(session.isComplete())
			.violations(session.violations)
			.pkKills(session.pkKills)
			.pkAverage(session.averageKillValue())
			.items(rows)
			.build();
	}

}

package com.rebuildbank;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.IntToLongFunction;
import net.runelite.api.gameval.ItemID;

/**
 * One temporary bank run. Pure data + ledger logic (no RuneLite types) so it can be
 * persisted with Gson and unit tested.
 *
 * The real bank is never modified. Every time the real bank is seen, it is
 * diffed against the last real bank we saw:
 *   - items that went IN first pay back anything owed to the real bank,
 *     the rest becomes part of the temporary bank;
 *   - items that went OUT come from the temporary bank first, then from the
 *     pool of untradeables that existed when the run started (if allowed, and
 *     possibly for a fee), then from the old bank (bought, or a rule break).
 */
public class RebuildSession
{
	public static final int TICK_MILLIS = 600;
	public static final int COINS = ItemID.COINS;
	public static final int PLATINUM = ItemID.PLATINUM;
	/** One platinum token is worth 1,000 coins. */
	public static final long PLATINUM_VALUE = 1000;

	public interface Policy
	{
		boolean isUntradeable(int itemId);

		/**
		 * Untradeables that always belong to the temporary bank, never locked or owed
		 * (the looting bag: you can only own one, so you couldn't get another).
		 */
		default boolean alwaysYours(int itemId)
		{
			return false;
		}

		/** Whether an existing untradeable may be unlocked (e.g. PvM gear only). */
		boolean isUnlockable(int itemId);

		UntradeableMode untradeableMode();

		/** Fee for taking one existing untradeable, under the current mode. */
		long untradeableCost(int itemId);

		/** Whether tradeables missing from the temporary bank may be bought from the old bank. */
		boolean buyTradeables();

		long tradeablePrice(int itemId);
	}

	/** What happened to one item in one bank update; used for chat messages. */
	public static final class Change
	{
		public final int itemId;
		public long deposited;
		public long repaid;
		/** Untradeables you started with, deposited: they join the locked untradeables. */
		public long locked;
		public long withdrawn;
		public long unlocked;
		public long unlockCost;
		public long bought;
		public long boughtCost;
		public long violated;

		Change(int itemId)
		{
			this.itemId = itemId;
		}
	}

	// ---- persisted state (Gson) ----
	long startedAtMillis;
	/** When this run was last saved; used to pick the newest of the settings copy and the backup file. */
	long savedAtMillis;
	long ticks;
	/** Tick count when the goal was reached, or -1. */
	long completedAtTicks = -1;
	/** True until the first real bank snapshot after starting has been taken. */
	boolean baselinePending;
	/** Paused: the timer stops and bank changes aren't tracked (they're your real bank's). */
	boolean paused;
	/** Just resumed: the next bank snapshot is taken as-is, so changes made while paused don't count. */
	boolean resyncPending;
	Map<Integer, Long> items = new HashMap<>();
	/**
	 * Owed to the real bank and shown in red until deposited back: tradeables you were
	 * carrying at the start, and anything taken out beyond what the temporary bank had.
	 */
	Map<Integer, Long> owed = new HashMap<>();
	/**
	 * Untradeables you were carrying when the run started and haven't deposited yet.
	 * They're pre-run items, so once deposited they're locked like the ones in your bank.
	 */
	Map<Integer, Long> carriedLocked = new HashMap<>();
	/** Untradeables that were in the real bank when the run started. */
	Map<Integer, Long> untradeablePool = new HashMap<>();
	Map<Integer, Long> lastRealBank = new HashMap<>();
	/** Unpaid debt (only when something was taken that your coins couldn't cover). */
	long spent;
	/** Total paid for unlocks and buys, from coins or debt. */
	long paid;
	long violations;
	/** Item types already paid for: unlocking is once per type, and permanent. */
	Set<Integer> unlockedTypes = new HashSet<>();
	long pkKills;
	long pkLootValue;
	GoalType goalType = GoalType.NONE;
	long goalTarget;
	int goalItemId = -1;
	String goalItemName;

	public static RebuildSession start(long nowMillis)
	{
		RebuildSession s = new RebuildSession();
		s.startedAtMillis = nowMillis;
		s.baselinePending = true;
		return s;
	}

	/**
	 * Everything you're carrying when the run starts is pre-run stuff. Tradeables came
	 * from your real bank, so they're owed until you deposit them back (using them up
	 * keeps them owed until replaced). Untradeables are locked: when you deposit them
	 * they join the locked untradeables, to unlock under your unlock settings.
	 * Untradeables you get during the run are yours. Both kinds show as owed until
	 * deposited. Returns how many items became owed.
	 */
	public long oweCarried(Map<Integer, Long> carried, Policy policy)
	{
		long total = 0;
		for (Map.Entry<Integer, Long> e : carried.entrySet())
		{
			if (policy.alwaysYours(e.getKey()))
			{
				continue; // yours: depositing it just adds it to the temporary bank
			}
			add(policy.isUntradeable(e.getKey()) ? carriedLocked : owed, e.getKey(), e.getValue());
			total += e.getValue();
		}
		return total;
	}

	/**
	 * Apply a fresh view of the real bank. The first call after starting only
	 * records the baseline (everything already there is "old bank").
	 */
	public List<Change> applyRealBank(Map<Integer, Long> real, Policy policy)
	{
		if (baselinePending)
		{
			lastRealBank = new HashMap<>(real);
			// added to (not replacing) the untradeables you were carrying at the start
			real.forEach((id, qty) ->
			{
				if (policy.alwaysYours(id))
				{
					add(items, id, qty); // already in the bank, and it's yours
				}
				else if (policy.isUntradeable(id))
				{
					add(untradeablePool, id, qty);
				}
			});
			baselinePending = false;
			return Collections.emptyList();
		}
		if (paused || resyncPending)
		{
			// whatever happened while paused belongs to the real bank
			lastRealBank = new HashMap<>(real);
			resyncPending = paused;
			return Collections.emptyList();
		}

		List<Change> changes = new ArrayList<>();
		Set<Integer> ids = new HashSet<>(real.keySet());
		ids.addAll(lastRealBank.keySet());

		for (int id : ids)
		{
			long delta = real.getOrDefault(id, 0L) - lastRealBank.getOrDefault(id, 0L);
			if (delta == 0)
			{
				continue;
			}

			Change c = new Change(id);
			if (delta > 0)
			{
				long rest = delta;
				long repaidOwed = Math.min(get(owed, id), rest);
				add(owed, id, -repaidOwed);
				rest -= repaidOwed;
				// untradeables you started with go to the locked section, not to you
				long locking = Math.min(get(carriedLocked, id), rest);
				add(carriedLocked, id, -locking);
				add(untradeablePool, id, locking);
				rest -= locking;
				add(items, id, rest);
				c.repaid = repaidOwed;
				c.locked = locking;
				c.deposited = rest;
			}
			else
			{
				long rest = -delta;

				long fromTemp = Math.min(get(items, id), rest);
				add(items, id, -fromTemp);
				c.withdrawn = fromTemp;
				rest -= fromTemp;

				// Backup only: normally locked items are blocked until unlocked from the bank
				if (rest > 0 && canUnlock(id, policy))
				{
					long fromPool = Math.min(get(untradeablePool, id), rest);
					if (fromPool > 0)
					{
						add(untradeablePool, id, -fromPool);
						c.unlocked = fromPool;
						c.unlockCost = unlockFee(id, policy);
						unlockedTypes.add(id);
						pay(c.unlockCost);
						rest -= fromPool;
					}
				}

				if (rest > 0 && canBuy(id, policy))
				{
					// only as many as the temporary bank's coins can pay for
					long price = policy.tradeablePrice(id);
					long affordable = Math.min(rest, count(COINS) / price);
					if (affordable > 0)
					{
						c.bought = affordable;
						c.boughtCost = price * affordable;
						pay(c.boughtCost);
						rest -= affordable;
					}
				}

				if (rest > 0)
				{
					add(owed, id, rest);
					c.violated = rest;
					violations++;
				}
			}
			changes.add(c);
		}

		lastRealBank = new HashMap<>(real);
		return changes;
	}

	private static boolean canBuy(int id, Policy policy)
	{
		return id != COINS && !policy.isUntradeable(id) && policy.buyTradeables() && policy.tradeablePrice(id) > 0;
	}


	/**
	 * Coins you may spend on a Grand Exchange buy offer: coins (and platinum tokens) in the
	 * temporary bank and in your inventory, minus coins you still owe your real bank and
	 * coins already promised to offers the plugin hasn't seen leave the bank yet.
	 */
	public long geSpendable(long invCoins, long invPlatinum, long reserved)
	{
		long have = count(COINS) + invCoins + (count(PLATINUM) + invPlatinum) * PLATINUM_VALUE;
		Map<Integer, Long> debt = getOwed();
		long owedCoins = debt.getOrDefault(COINS, 0L) + debt.getOrDefault(PLATINUM, 0L) * PLATINUM_VALUE;
		return Math.max(0, have - owedCoins - reserved);
	}

	/**
	 * Everything that has to go back into the bank (id -> quantity): tradeables owed to the
	 * real bank, plus untradeables you started with that haven't been deposited yet (those
	 * go to the locked section when deposited).
	 */
	public Map<Integer, Long> getOwed()
	{
		Map<Integer, Long> all = new HashMap<>(owed);
		carriedLocked.forEach((id, qty) -> all.merge(id, qty, Long::sum));
		return Collections.unmodifiableMap(all);
	}

	public long owedValue(IntToLongFunction unitPrice)
	{
		long total = 0;
		for (Map.Entry<Integer, Long> e : getOwed().entrySet())
		{
			total += unitPrice.applyAsLong(e.getKey()) * e.getValue();
		}
		return total;
	}

	private static boolean canUnlock(int id, Policy policy)
	{
		return policy.untradeableMode() != UntradeableMode.NOT_ALLOWED
			&& policy.isUntradeable(id) && policy.isUnlockable(id);
	}

	/** Whether this item is a locked existing untradeable that can be unlocked right now. */
	public boolean canUnlockNow(int itemId, Policy policy)
	{
		return poolCount(itemId) > 0 && canUnlock(itemId, policy);
	}

	/** Existing untradeables you could unlock right now (id -> quantity). */
	public Map<Integer, Long> unlockable(Policy policy)
	{
		Map<Integer, Long> out = new HashMap<>();
		untradeablePool.forEach((id, qty) ->
		{
			if (canUnlock(id, policy))
			{
				out.put(id, qty);
			}
		});
		return out;
	}

	/**
	 * Unlock an existing untradeable: it moves from the old bank into the
	 * temporary bank (it never leaves the real bank), paying the fee if any.
	 * Returns null if it can't be unlocked, or a change with unlocked == 0 if
	 * the temporary bank doesn't have enough coins.
	 */
	public Change unlock(int itemId, Policy policy)
	{
		long qty = poolCount(itemId);
		if (qty <= 0 || !canUnlock(itemId, policy))
		{
			return null;
		}
		Change c = new Change(itemId);
		c.unlocked = qty;
		c.unlockCost = unlockFee(itemId, policy);
		if (c.unlockCost > count(COINS))
		{
			c.unlocked = 0; // can't afford it
			return c;
		}
		untradeablePool.remove(itemId);
		add(items, itemId, qty);
		unlockedTypes.add(itemId);
		pay(c.unlockCost);
		return c;
	}

	/** One fee per item type (the whole stack), and nothing once it's been paid. */
	public long unlockFee(int itemId, Policy policy)
	{
		return unlockedTypes.contains(itemId) ? 0 : policy.untradeableCost(itemId);
	}


	public void recordKill(long lootValue)
	{
		pkKills++;
		pkLootValue += Math.max(0, lootValue);
	}

	public void addKillLoot(long lootValue)
	{
		pkLootValue += Math.max(0, lootValue);
	}

	public long averageKillValue()
	{
		return pkKills <= 0 ? 0 : pkLootValue / pkKills;
	}

	/**
	 * Pay from the coins in the temporary bank. The coins stay in your real
	 * bank but go back to being "old bank". Anything coins can't cover is debt.
	 */
	private void pay(long cost)
	{
		if (cost <= 0)
		{
			return;
		}
		long fromCoins = Math.min(count(COINS), cost);
		add(items, COINS, -fromCoins);
		spent += cost - fromCoins;
		paid += cost;
	}

	/** Items you own in the temporary bank. */
	public long count(int itemId)
	{
		return get(items, itemId);
	}

	/** Existing untradeables still waiting in the old bank. */
	public long poolCount(int itemId)
	{
		return get(untradeablePool, itemId);
	}

	/** How many of an item can be withdrawn without breaking the rules (Long.MAX_VALUE = unlimited). */
	public long withdrawable(int itemId, Policy policy)
	{
		long n = count(itemId);
		if (canBuy(itemId, policy))
		{
			// plus as many as the temporary bank's coins can buy
			n += count(COINS) / policy.tradeablePrice(itemId);
		}
		return n;
	}

	/**
	 * How many a bank "Withdraw-..." option takes, or -1 when it isn't known up front
	 * (Withdraw-X opens a prompt). "Withdraw-500" is the remembered last-X amount.
	 */
	public static long requestedAmount(String option, long realCount)
	{
		String suffix = option.substring("Withdraw".length()).replaceFirst("^-", "").trim();
		switch (suffix.toLowerCase(Locale.ROOT))
		{
			case "all":
				return realCount;
			case "all-but-1":
				return Math.max(0, realCount - 1);
			default:
				try
				{
					return Long.parseLong(suffix);
				}
				catch (NumberFormatException ex)
				{
					return -1; // Withdraw-X, or anything unexpected
				}
		}
	}

	/**
	 * Whether a withdraw would take more than the temporary bank allows. When the
	 * amount isn't known yet (Withdraw-X), only block if nothing at all is allowed.
	 */
	public static boolean overdraws(long wanted, long realCount, long allowed)
	{
		return wanted < 0 ? allowed <= 0 : Math.min(wanted, realCount) > allowed;
	}

	public long bankValue(IntToLongFunction unitPrice)
	{
		long total = 0;
		for (Map.Entry<Integer, Long> e : items.entrySet())
		{
			total += unitPrice.applyAsLong(e.getKey()) * e.getValue();
		}
		return total;
	}

	/**
	 * What the run is worth: the temporary bank's value minus anything owed to the real
	 * bank, never below 0. Items bought with owed (real-bank) coins don't count until
	 * the debt is paid back.
	 */
	public long netValue(IntToLongFunction unitPrice)
	{
		return Math.max(0, bankValue(unitPrice) - spent - owedValue(unitPrice));
	}

	/** Current progress towards the goal, in the goal's own unit. */
	public long goalProgress(IntToLongFunction unitPrice, int coinsId)
	{
		switch (goalType)
		{
			case NET_VALUE:
				return netValue(unitPrice);
			case COINS:
				return count(coinsId);
			case ITEM:
				return goalItemId >= 0 ? count(goalItemId) : 0;
			default:
				return 0;
		}
	}

	public boolean hasGoal()
	{
		return goalType != GoalType.NONE && goalTarget > 0;
	}

	public boolean isComplete()
	{
		return completedAtTicks >= 0;
	}

	/** Ticks counted towards the challenge (frozen once the goal is reached). */
	public long challengeTicks()
	{
		return isComplete() ? completedAtTicks : ticks;
	}

	public boolean isTiming()
	{
		return !baselinePending && !paused && !isComplete();
	}

	public void pause()
	{
		paused = true;
	}

	/** The next bank snapshot is taken as the new starting point, so nothing from the pause counts. */
	public void resume()
	{
		paused = false;
		resyncPending = true;
	}

	/** Tradeables owed and unpaid costs; starting untradeables still waiting to be deposited aren't debt. */
	public boolean hasDebt()
	{
		return spent > 0 || owed.values().stream().anyMatch(q -> q > 0);
	}

	/**
	 * Forgives all debt: owed tradeables and unpaid costs. For mistakes, e.g. a shop or the
	 * Grand Exchange taking coins straight from the real bank. Starting untradeables still
	 * go to the locked section when deposited.
	 */
	public void clearDebt()
	{
		owed.clear();
		spent = 0;
	}

	/** How many of this item are owed to the real bank (tradeable debt only). */
	public long debtCount(int itemId)
	{
		return get(owed, itemId);
	}

	/** Forgives the debt for one item. Returns how many were owed. */
	public long clearDebt(int itemId)
	{
		long qty = get(owed, itemId);
		owed.remove(itemId);
		return qty;
	}

	/**
	 * Takes an item's whole stack out of the temporary bank, e.g. something deposited that
	 * wasn't obtained fairly. It stays in your bank but counts as real bank again, so taking
	 * it out later is treated like any other real-bank item. Returns how many were moved.
	 */
	public long moveToRealBank(int itemId)
	{
		long qty = get(items, itemId);
		items.remove(itemId);
		return qty;
	}

	public static long gpPerHour(long value, long ticks)
	{
		if (ticks <= 0)
		{
			return 0;
		}
		return (long) (value * 3_600_000.0 / (ticks * (double) TICK_MILLIS));
	}

	public static String formatTicks(long ticks)
	{
		return formatSeconds(ticks * TICK_MILLIS / 1000);
	}

	public static String formatSeconds(long secs)
	{
		return String.format("%d:%02d:%02d", secs / 3600, (secs / 60) % 60, secs % 60);
	}

	public Map<Integer, Long> getItems()
	{
		return Collections.unmodifiableMap(items);
	}

	private static long get(Map<Integer, Long> m, int id)
	{
		return m.getOrDefault(id, 0L);
	}

	private static void add(Map<Integer, Long> m, int id, long qty)
	{
		long v = m.getOrDefault(id, 0L) + qty;
		if (v <= 0)
		{
			m.remove(id);
		}
		else
		{
			m.put(id, v);
		}
	}
}

package com.rebuildbank;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** In-game timer. Counts down to the time limit, then flashes slowly. */
class TimerOverlay extends OverlayPanel
{
	private static final Color FLASH_COLOR = new Color(170, 20, 20, 200);
	private static final long FLASH_PERIOD_MS = 1000; // 1s on, 1s off
	private static final int WIDE = 160;

	private final RebuildBankPlugin plugin;
	private final RebuildBankConfig config;

	@Inject
	TimerOverlay(RebuildBankPlugin plugin, RebuildBankConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		RebuildSession s = plugin.getSession();
		if (!config.showOverlay() || s == null)
		{
			return null;
		}

		long elapsedSecs = s.challengeTicks() * RebuildSession.TICK_MILLIS / 1000;
		long limitSecs = Math.max(0, config.timeLimitMinutes()) * 60L;
		boolean overTime = limitSecs > 0 && elapsedSecs >= limitSecs;
		boolean flashOn = overTime && !s.isComplete() && (System.currentTimeMillis() / FLASH_PERIOD_MS) % 2 == 0;

		panelComponent.setPreferredSize(new Dimension(ComponentConstants.STANDARD_WIDTH, 0));
		panelComponent.setBackgroundColor(flashOn ? FLASH_COLOR : ComponentConstants.STANDARD_BACKGROUND_COLOR);
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Rebuild Bank")
			.color(s.isComplete() ? Color.GREEN : Color.ORANGE)
			.build());

		if (s.baselinePending)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("Open your bank to start").build());
			return super.render(graphics);
		}

		if (s.paused || s.resyncPending)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(s.paused ? "Paused" : "Resumed - open your bank")
				.leftColor(Color.YELLOW)
				.build());
		}
		if (limitSecs > 0 && config.overlayTimeLeft())
		{
			String left = overTime
				? "+" + RebuildSession.formatSeconds(elapsedSecs - limitSecs)
				: RebuildSession.formatSeconds(limitSecs - elapsedSecs);
			line(overTime ? "Time's up" : "Time left", left, overTime ? Color.RED : Color.WHITE);
		}
		if (config.overlayElapsed())
		{
			line("Elapsed", RebuildSession.formatSeconds(elapsedSecs), Color.WHITE);
		}
		GoalDisplay goal = config.overlayGoal();
		if (s.hasGoal() && goal != GoalDisplay.OFF)
		{
			if (goal == GoalDisplay.BOTH)
			{
				// "12.5m / 50m (25%)" doesn't fit the standard overlay width
				panelComponent.setPreferredSize(new Dimension(WIDE, 0));
			}
			line("Goal", goalText(s, goal), s.isComplete() ? Color.GREEN : Color.WHITE);
		}
		if (config.overlayNetValue())
		{
			line("Net value", Amounts.shortFormat(plugin.getCachedNetValue()), Color.WHITE);
		}
		if (config.overlayGpHr())
		{
			line("GP/hr", Amounts.shortFormat(RebuildSession.gpPerHour(plugin.getCachedNetValue(), s.challengeTicks())), Color.WHITE);
		}
		if (config.overlayOwed() && plugin.getCachedOwedValue() > 0)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Owed")
				.leftColor(Color.RED)
				.right("-" + Amounts.shortFormat(plugin.getCachedOwedValue()))
				.rightColor(Color.RED)
				.build());
		}
		if (config.overlayPks() && s.pkKills > 0)
		{
			line("PKs", Long.toString(s.pkKills), Color.WHITE);
			line("Avg kill", Amounts.shortFormat(s.averageKillValue()), Color.WHITE);
		}
		return super.render(graphics);
	}

	private void line(String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build());
	}

	/** "12.5m / 50m", "25%" or "12.5m / 50m (25%)"; for an item goal the numbers are item counts. */
	static String goalText(long progress, long target, boolean complete, GoalDisplay display)
	{
		long pct = target <= 0 ? 0 : Math.max(0, Math.min(100, progress * 100 / target));
		String value = Amounts.shortFormat(Math.min(progress, target)) + " / " + Amounts.shortFormat(target);
		String percent = complete ? "Done!" : pct + "%";
		switch (display)
		{
			case VALUE:
				return complete ? value + " Done!" : value;
			case BOTH:
				return value + " (" + percent + ")";
			case PERCENT:
			default:
				return percent;
		}
	}

	private String goalText(RebuildSession s, GoalDisplay display)
	{
		return goalText(plugin.getCachedGoalProgress(), s.goalTarget, s.isComplete(), display);
	}
}

