package com.rebuildbank;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * A list of item names typed by the player, each with an optional price:
 * <pre>
 * Fire cape: 1m
 * Graceful*
 * Barrows gloves = 130k
 * </pre>
 * One entry per line, or separated by ";" or ",". A comma followed by a digit is part of a
 * number ("1,000,000"), not a separator. A trailing * matches any ending.
 */
final class UnlockList
{
	static final UnlockList EMPTY = new UnlockList(Collections.emptyList());

	private static final class Entry
	{
		final String pattern;
		final long price;

		Entry(String pattern, long price)
		{
			this.pattern = pattern;
			this.price = price;
		}

		boolean wildcard()
		{
			return pattern.endsWith("*");
		}

		boolean matches(String lowerName)
		{
			return wildcard() ? lowerName.startsWith(pattern.substring(0, pattern.length() - 1)) : lowerName.equals(pattern);
		}
	}

	private final List<Entry> entries;

	private UnlockList(List<Entry> entries)
	{
		this.entries = entries;
	}

	static UnlockList parse(String text)
	{
		List<Entry> out = new ArrayList<>();
		if (text != null)
		{
			for (String part : text.split("[\\n;]|,(?!\\d)"))
			{
				String name = part.trim();
				long price = -1;
				int sep = Math.max(name.lastIndexOf(':'), name.lastIndexOf('='));
				if (sep > 0)
				{
					long v = Amounts.parse(name.substring(sep + 1));
					if (v >= 0)
					{
						price = v;
						name = name.substring(0, sep).trim();
					}
				}
				if (!name.isEmpty())
				{
					out.add(new Entry(name.toLowerCase(Locale.ROOT), price));
				}
			}
		}
		return out.isEmpty() ? EMPTY : new UnlockList(out);
	}

	boolean isEmpty()
	{
		return entries.isEmpty();
	}

	boolean contains(String itemName)
	{
		String n = itemName.toLowerCase(Locale.ROOT);
		for (Entry e : entries)
		{
			if (e.matches(n))
			{
				return true;
			}
		}
		return false;
	}

	/** The price set for this item (an exact name wins over a * pattern), or -1 if none. */
	long price(String itemName)
	{
		String n = itemName.toLowerCase(Locale.ROOT);
		long wildcardPrice = -1;
		for (Entry e : entries)
		{
			if (e.price >= 0 && e.matches(n))
			{
				if (!e.wildcard())
				{
					return e.price;
				}
				if (wildcardPrice < 0)
				{
					wildcardPrice = e.price;
				}
			}
		}
		return wildcardPrice;
	}

	/**
	 * Adds the entries of {@code extra} that {@code base} doesn't already name, one per line.
	 * Used to fold the old "Custom costs" setting into the unlock list.
	 */
	static String merge(String base, String extra)
	{
		UnlockList have = parse(base);
		StringBuilder sb = new StringBuilder(base == null ? "" : base.trim());
		if (extra != null)
		{
			for (String part : extra.split("[\\n;]|,(?!\\d)"))
			{
				String line = part.trim();
				UnlockList one = parse(line);
				if (one.isEmpty())
				{
					continue;
				}
				Entry add = one.entries.get(0);
				// skip names already listed, unless only the new line has a price
				// (the priced line is added as well, so the price isn't lost)
				if (have.entries.stream().anyMatch(e -> e.pattern.equals(add.pattern) && (e.price >= 0 || add.price < 0)))
				{
					continue;
				}
				if (sb.length() > 0)
				{
					sb.append('\n');
				}
				sb.append(line);
			}
		}
		return sb.toString();
	}
}

