	@Test
	public void changesWhilePausedDontCount()
	{
		RebuildSession s = RebuildSession.start(0);
		s.applyRealBank(bank(COINS, 50_000_000, WHIP, 3), STRICT);
		s.applyRealBank(bank(COINS, 50_000_000, WHIP, 3, LOBSTER, 20), STRICT);
		assertEquals(20, s.count(LOBSTER));

		s.pause();
		assertFalse(s.isTiming());
		// paused: take a whip and 10m out, put 5 lobsters in - none of it counts
		s.applyRealBank(bank(COINS, 40_000_000, WHIP, 2, LOBSTER, 25), STRICT);
		assertTrue(s.getOwed().isEmpty());
		assertEquals(20, s.count(LOBSTER));

		s.resume();
		assertTrue(s.isTiming());
		// first snapshot after resuming is the new starting point
		s.applyRealBank(bank(COINS, 40_000_000, WHIP, 2, LOBSTER, 25), STRICT);
		assertTrue(s.getOwed().isEmpty());
		// tracking works again after that
		s.applyRealBank(bank(COINS, 40_000_000, WHIP, 2, LOBSTER, 30), STRICT);
		assertEquals(25, s.count(LOBSTER));
	}

	@Test
	public void clearingDebtForgivesOwedItems()
	{
		RebuildSession s = RebuildSession.start(0);
		s.oweCarried(bank(FIRE_CAPE, 1), STRICT); // a starting untradeable: not debt
		s.applyRealBank(bank(COINS, 1_000_000), STRICT);
		s.applyRealBank(bank(COINS, 940_000), STRICT); // a shop took 60k from the real bank
		assertTrue(s.hasDebt());
		assertEquals(Long.valueOf(60_000), s.getOwed().get(COINS));

		s.clearDebt();
		assertFalse(s.hasDebt());
		assertEquals(null, s.getOwed().get(COINS));
		assertEquals(Long.valueOf(1), s.getOwed().get(FIRE_CAPE)); // still locked when deposited
	}

	@Test
	public void clearOneItemsDebt()
	{
		RebuildSession s = RebuildSession.start(0);
		s.applyRealBank(bank(COINS, 1_000_000, LOBSTER, 50), STRICT);
		s.applyRealBank(bank(COINS, 984_000, LOBSTER, 40), STRICT); // GE took 16k, 10 lobsters taken
		assertEquals(16_000, s.debtCount(COINS));
		assertEquals(10, s.debtCount(LOBSTER));

		assertEquals(16_000, s.clearDebt(COINS));
		assertEquals(0, s.debtCount(COINS));
		assertEquals(10, s.debtCount(LOBSTER)); // other debt untouched
		assertEquals(0, s.clearDebt(WHIP)); // nothing owed: no-op
	}

	@Test
	public void movingAStackToTheRealBank()
	{
		final int AIR_RUNE = 556;
		RebuildSession s = RebuildSession.start(0);
		s.applyRealBank(bank(COINS, 100_000), STRICT);
		s.applyRealBank(bank(COINS, 100_000, AIR_RUNE, 1000), STRICT); // deposited runes bought with real coins
		assertEquals(1000, s.count(AIR_RUNE));

		assertEquals(1000, s.moveToRealBank(AIR_RUNE));
		assertEquals(0, s.count(AIR_RUNE));
		// they're real-bank items now: depositing more only adds the new ones
		s.applyRealBank(bank(COINS, 100_000, AIR_RUNE, 1100), STRICT);
		assertEquals(100, s.count(AIR_RUNE));
		// and taking real-bank runes out is a rule break, as for any real item
		s.applyRealBank(bank(COINS, 100_000, AIR_RUNE, 900), STRICT);
		assertEquals(0, s.count(AIR_RUNE));
		assertEquals(100, s.debtCount(AIR_RUNE));
	}
